export function ForgeMark(options: {
  size?: keyof typeof SIZE;
  showWordmark?: boolean;
  className?: string;
}) {
  const { size = "md", showWordmark = true, className } = options;
  const s = SIZE[size];
  return (
    <span
      className={cn(
        "inline-flex items-center font-semibold tracking-tight text-foreground",
        s.gap,
        className
      )}
    >
      <ForgeMarkIcon className={cn(s.icon, "shrink-0")} />
      {showWordmark && <span className={s.text}>Forge</span>}
    </span>
  );
}

export function ForgeMarkLink(options: {
  to?: string;
  size?: keyof typeof SIZE;
  showWordmark?: boolean;
  className?: string;
}) {
  const { to = "/", size = "sm", showWordmark = true, className } = options;
  return (
    <Link
      to={to}
      aria-label="Forge home"
      className={cn("inline-flex rounded-lg hover:opacity-90", className)}
    >
      <ForgeMark size={size} showWordmark={showWordmark} />
    </Link>
  );
}
